<?php require_once __DIR__.'/../includes/bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=$_POST['action']??'';if($action==='create'){$title=trim($_POST['title']??'');$company=trim($_POST['company']??'');$type=trim($_POST['type']??'Internship');$location=trim($_POST['location']??'');$mode=trim($_POST['work_mode']??'Hybrid');$comp=trim($_POST['compensation']??'');$skills=trim($_POST['skills']??'');$desc=trim($_POST['description']??'');if($title&&$company&&$desc){$q=$pdo->prepare('INSERT INTO opportunities(title,company,type,location,work_mode,compensation,skills,description,created_by) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$title,$company,$type,$location,$mode,$comp,$skills,$desc,$_SESSION['user']['id']]);flash('Opportunity added.');}else flash('Title, company, and description are required.','error');}elseif($action==='toggle'){$id=(int)$_POST['id'];$pdo->prepare('UPDATE opportunities SET is_active=1-is_active WHERE id=?')->execute([$id]);flash('Opportunity visibility updated.');}header('Location: opportunities.php');exit;}$jobs=$pdo->query('SELECT o.*,COUNT(a.id) AS application_count FROM opportunities o LEFT JOIN applications a ON a.opportunity_id=o.id GROUP BY o.id ORDER BY o.created_at DESC')->fetchAll();$apps=$pdo->query('SELECT a.id,a.status,a.applied_at,u.name,u.email,o.title,o.company FROM applications a JOIN users u ON u.id=a.user_id JOIN opportunities o ON o.id=a.opportunity_id ORDER BY a.applied_at DESC')->fetchAll();header_html('Manage Opportunities'); ?>
<div class="row"><div><h1>Placement admin</h1><p class="muted">Add opportunities and update student application status.</p></div></div><section class="form-card"><h2>Add opportunity</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><div class="field"><label>Role title *</label><input name="title" required maxlength="150"></div><div class="field"><label>Company *</label><input name="company" required maxlength="150"></div><div class="grid"><div class="field"><label>Type</label><select name="type"><option>Internship</option><option>Full-time</option><option>Part-time</option></select></div><div class="field"><label>Work mode</label><select name="work_mode"><option>Hybrid</option><option>Remote</option><option>On-site</option></select></div></div><div class="field"><label>Location</label><input name="location" maxlength="150"></div><div class="field"><label>Stipend / Salary</label><input name="compensation" maxlength="100"></div><div class="field"><label>Skills</label><input name="skills" maxlength="255" placeholder="PHP, MySQL, HTML"></div><div class="field"><label>Description *</label><textarea name="description" required maxlength="2000"></textarea></div><button type="submit">Add opportunity</button></form></section>
<section class="panel"><h2>Opportunities</h2><div class="table-wrap"><table><tr><th>Role</th><th>Type</th><th>Applications</th><th>Visibility</th><th>Action</th></tr><?php foreach($jobs as $j):?><tr><td><strong><?=e($j['title'])?></strong><br><?=e($j['company'])?></td><td><?=e($j['type'])?></td><td><?=$j['application_count']?></td><td><?=$j['is_active']?'Active':'Hidden'?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$j['id']?>"><button class="secondary" type="submit"><?=$j['is_active']?'Hide':'Publish'?></button></form></td></tr><?php endforeach;?></table></div></section>
<section class="panel"><h2>All applications</h2><div class="table-wrap"><table><tr><th>Student</th><th>Opportunity</th><th>Date</th><th>Status / Update</th></tr><?php foreach($apps as $a):?><tr><td><?=e($a['name'])?><br><span class="small muted"><?=e($a['email'])?></span></td><td><?=e($a['company'])?><br><?=e($a['title'])?></td><td><?=e(date('d M Y',strtotime($a['applied_at'])))?></td><td><form method="post" action="update_status.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$a['id']?>"><select name="status"><?php foreach(['Pending','Shortlisted','Interview','Offer','Rejected'] as $s):?><option <?=$a['status']===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select><button type="submit">Save</button></form></td></tr><?php endforeach;?></table></div></section><?php footer_html(); ?>
